  INSERT INTO lpm_schema_elements (id, project_id, element_type, label, parent_id, metadata, status)
  VALUES
  ('d68724fa-f299-5752-a49b-789f6416270d', v_project_id, 'concept', $J$Adaptation$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-adaptation", "vocabulary": "BIO-CORE-v1.0.0", "definition": "A heritable trait that increases an organism's fitness within a given environment, shaped by natural selection over generations."}$J$::jsonb, 'accepted'),
  ('d34950cc-ba40-5ea7-9d9c-37a4dd862ac3', v_project_id, 'concept', $J$Allele$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-allele", "vocabulary": "BIO-CORE-v1.0.0", "definition": "One of two or more alternative forms of a gene occupying the same locus on a chromosome."}$J$::jsonb, 'accepted'),
  ('adbf8407-2108-56e2-9137-9a5c4baaacd7', v_project_id, 'concept', $J$Common Ancestor$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-common-ancestor", "vocabulary": "BIO-CORE-v1.0.0", "definition": "An organism or population from which two or more descendant lineages have diverged."}$J$::jsonb, 'accepted'),
  ('0a4e7493-b758-51bd-a331-5baa7330c318', v_project_id, 'concept', $J$Drift$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-drift", "vocabulary": "BIO-CORE-v1.0.0", "definition": "Random fluctuation of allele frequencies within a population from one generation to the next, independent of selective advantage."}$J$::jsonb, 'accepted'),
  ('edfd16ab-0aca-5aa8-b79b-d059383c9d04', v_project_id, 'concept', $J$Extinction$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-extinction", "vocabulary": "BIO-CORE-v1.0.0", "definition": "The complete disappearance of a species or other taxonomic group, ending its lineage."}$J$::jsonb, 'accepted'),
  ('3f10e010-2780-57e2-aae0-62631276a8b0', v_project_id, 'concept', $J$Fitness$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-fitness", "vocabulary": "BIO-CORE-v1.0.0", "definition": "The relative reproductive success of a genotype or phenotype, typically measured as expected number of offspring contributing to the next generation."}$J$::jsonb, 'accepted'),
  ('edba5b0a-400d-5b77-a2b3-672ff3ad13bd', v_project_id, 'concept', $J$Gene$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-gene", "vocabulary": "BIO-CORE-v1.0.0", "definition": "A heritable unit of DNA that functions as a basic unit of inheritance, typically encoding information for a specific product or trait."}$J$::jsonb, 'accepted'),
  ('cae5dbad-0106-51c0-8818-aaacab89470e', v_project_id, 'concept', $J$Inheritance$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-inheritance", "vocabulary": "BIO-CORE-v1.0.0", "definition": "The transmission of genetic information from parent to offspring."}$J$::jsonb, 'accepted'),
  ('eeb66b9f-2d89-5cae-bed1-eac6f60037b1', v_project_id, 'concept', $J$Mutation$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-mutation", "vocabulary": "BIO-CORE-v1.0.0", "definition": "A heritable change in a DNA sequence, serving as an ultimate source of genetic variation within a population."}$J$::jsonb, 'accepted'),
  ('f0abb875-7374-5581-b9fc-5c18f78006cc', v_project_id, 'concept', $J$Natural Selection$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-natural-selection", "vocabulary": "BIO-CORE-v1.0.0", "definition": "Differential reproductive success among heritable variants within a population, resulting from their interaction with the environment."}$J$::jsonb, 'accepted'),
  ('3bb15af5-a22b-512d-a3fb-708bc38f3d87', v_project_id, 'concept', $J$Phylogeny$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-phylogeny", "vocabulary": "BIO-CORE-v1.0.0", "definition": "The evolutionary history and relatedness of a group of organisms, typically represented as a branching tree."}$J$::jsonb, 'accepted'),
  ('ae00fa14-acc2-5c38-8d0b-ff39d58f839e', v_project_id, 'concept', $J$Population$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-population", "vocabulary": "BIO-CORE-v1.0.0", "definition": "A group of interbreeding organisms of the same species occupying a defined geographic area at a given time."}$J$::jsonb, 'accepted'),
  ('61579884-3cfe-51b7-9575-8163446a16ea', v_project_id, 'concept', $J$Selection Pressure$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-selection-pressure", "vocabulary": "BIO-CORE-v1.0.0", "definition": "An environmental or biological factor that reduces or increases reproductive success of particular variants within a population, driving the direction of selection."}$J$::jsonb, 'accepted'),
  ('d79b98a7-92f7-5e80-be19-4223c8d86e01', v_project_id, 'concept', $J$Speciation$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-speciation", "vocabulary": "BIO-CORE-v1.0.0", "definition": "The evolutionary process by which populations diverge to become distinct, reproductively isolated species."}$J$::jsonb, 'accepted'),
  ('c0d6c5da-a3f4-5338-9a53-8fe66748a013', v_project_id, 'concept', $J$Species$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-bio-core-species", "vocabulary": "BIO-CORE-v1.0.0", "definition": "A group of organisms capable of interbreeding and producing fertile offspring, generally reproductively isolated from other such groups."}$J$::jsonb, 'accepted')
  INSERT INTO lpm_data_objects (id, project_id, object_type, title, description, grade_band, subject_area, content, status)
  VALUES
  ('d8df353a-aa76-5d37-b5b4-a0cd3f1d4860', v_project_id, 'strand', $J$Variation and Inheritance$J$, $J$Foundational strand establishing that individuals vary and that traits are transmitted from parent to offspring -- the raw material on which Strand 2 (Natural Selection) and Strand 3 (Speciation) both depend. Concepts introduced here (Gene, Allele, Population, Inheritance) are deliberately reinforced throughout the other two strands rather than confined to this one, to maximize horizontal coherence.$J$, $J$K-12$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-variation-inheritance", "description": "Foundational strand establishing that individuals vary and that traits are transmitted from parent to offspring -- the raw material on which Strand 2 (Natural Selection) and Strand 3 (Speciation) both depend. Concepts introduced here (Gene, Allele, Population, Inheritance) are deliberately reinforced throughout the other two strands rather than confined to this one, to maximize horizontal coherence.", "associatedDomains": ["Biology"], "relations": {"prerequisiteOf": ["OE-STRAND-bio-core-k12-speciation-diversity"], "foundationalTo": ["OE-STRAND-bio-core-k12-natural-selection-adaptation"]}, "epistemicStatus": "designed-thought-experiment", "_source": {"repo": "bio-core-k12", "path": "strands/strand-101-variation-inheritance.yaml"}}$J$::jsonb, 'draft'),
  ('8e62e70a-437d-540d-83f6-90a0fe54783a', v_project_id, 'substrand', $J$Noticing Variation and Family Resemblance$J$, $J$Key concepts: Population, Inheritance$J$, $J$K-2$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-variation-inheritance-k2", "performanceIndicators": ["Identifies visible differences among individuals of the same familiar species (e.g., dog coat color, leaf shape).", "Describes ways offspring resemble their parents (e.g., puppies look like their parent dogs).", "Sorts a group of similar organisms and notices that no two individuals are identical."], "concepts": [{"id": "OE-CONCEPT-bio-core-population", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-inheritance", "emphasis": "primary"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-101-variation-inheritance.yaml"}}$J$::jsonb, 'draft'),
  ('70cf40f5-cb5d-508a-95dc-d18eaa465e94', v_project_id, 'substrand', $J$Heritable Traits and Simple Population Description$J$, $J$Key concepts: Inheritance, Population$J$, $J$3-5$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-variation-inheritance-35", "performanceIndicators": ["Distinguishes traits that are inherited (eye color) from characteristics acquired during a lifetime (a scar, a learned trick).", "Describes a population as a group of the same kind of organism living in one area.", "Predicts that offspring in a population will show a mix of trait variants similar to those of their parent generation."], "concepts": [{"id": "OE-CONCEPT-bio-core-inheritance", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-population", "emphasis": "primary"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-101-variation-inheritance.yaml"}}$J$::jsonb, 'draft'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', v_project_id, 'substrand', $J$Genes, Alleles, and the Origin of Variation$J$, $J$Key concepts: Gene, Allele, Mutation, Population$J$, $J$6-8$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-variation-inheritance-68", "performanceIndicators": ["Explains that genes are units of inheritance and that alleles are alternate forms of a gene.", "Explains that mutation is a random source of new heritable variation, not directed by an organism's needs.", "Describes a population in terms of the range of allele variants present within it, not a single fixed 'type.'"], "concepts": [{"id": "OE-CONCEPT-bio-core-gene", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-allele", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-mutation", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-population", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-101-variation-inheritance.yaml"}}$J$::jsonb, 'draft'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', v_project_id, 'substrand', $J$Population-Level Genetics and Allele Frequency$J$, $J$Key concepts: Gene, Allele, Population, Mutation, Drift, Selection Pressure$J$, $J$9-12$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-variation-inheritance-912", "performanceIndicators": ["Describes a population in terms of allele frequencies and explains that these frequencies can change across generations.", "Distinguishes changes in allele frequency caused by selection pressure from changes caused by drift.", "Uses a simple quantitative model (e.g., a bead or simulation activity) to track allele frequency change over generations."], "concepts": [{"id": "OE-CONCEPT-bio-core-gene", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-allele", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-population", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-mutation", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-drift", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-selection-pressure", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-101-variation-inheritance.yaml"}}$J$::jsonb, 'draft'),
  ('d1b088f7-a940-5d5e-a5bc-45c0a049d351', v_project_id, 'strand', $J$Natural Selection and Adaptation$J$, $J$The central mechanistic strand. Builds the full four-component natural selection model (variation, heritability, differential reproduction, population-level change) using exclusively decentralized causal vocabulary -- BIO-CORE contains no organism-agency concepts, so this strand is structurally incapable of invoking behavioral niche selection or agential framing. This is a direct consequence of vocabulary scope, not an instructional simplification layered on top of richer content.$J$, $J$K-12$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-natural-selection-adaptation", "description": "The central mechanistic strand. Builds the full four-component natural selection model (variation, heritability, differential reproduction, population-level change) using exclusively decentralized causal vocabulary -- BIO-CORE contains no organism-agency concepts, so this strand is structurally incapable of invoking behavioral niche selection or agential framing. This is a direct consequence of vocabulary scope, not an instructional simplification layered on top of richer content.", "associatedDomains": ["Biology"], "relations": {"prerequisiteOf": ["OE-STRAND-bio-core-k12-speciation-diversity"]}, "epistemicStatus": "designed-thought-experiment", "_source": {"repo": "bio-core-k12", "path": "strands/strand-102-natural-selection-adaptation.yaml"}, "disputeInstantiation": "This strand's structural incapacity to invoke organism agency genuinely instantiates the decentralized-causal-reasoning (DCR) position (TheoryBase OE-THEORY-dichotomized-causal-reasoning) in the real, published dispute with Kampourakis (2020) / Nehm & Kampourakis (2022) -- see openevo-graph's nodes/disputes/dispute-openevo-vs-kampourakis.yaml, whose instantiatesIn edge already points at this strand's id."}$J$::jsonb, 'draft'),
  ('aac5e307-a98f-50c6-ba5d-5cc6bcd7ebdf', v_project_id, 'substrand', $J$Organisms and Their Habitats$J$, $J$Key concepts: Adaptation$J$, $J$K-2$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-natural-selection-adaptation-k2", "performanceIndicators": ["Describes features of a familiar organism that help it survive in its habitat (e.g., thick fur in a cold place).", "Recognizes that some individuals in a group survive a challenge (like a harsh winter) while others do not."], "concepts": [{"id": "OE-CONCEPT-bio-core-adaptation", "emphasis": "primary"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-102-natural-selection-adaptation.yaml"}}$J$::jsonb, 'draft'),
  ('ae85f5be-aead-5819-99df-8b3d431f79d1', v_project_id, 'substrand', $J$Trait Advantage and Simple Selection Scenarios$J$, $J$Key concepts: Natural Selection, Adaptation, Inheritance$J$, $J$3-5$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-natural-selection-adaptation-35", "performanceIndicators": ["Predicts which trait variant will become more common in a population over several generations, given a simple environmental scenario.", "Explains a prediction using inherited variation and differential survival, without invoking organism need or effort.", "Distinguishes 'this trait helped some individuals survive better' from 'organisms grew this trait because they needed it.'"], "concepts": [{"id": "OE-CONCEPT-bio-core-natural-selection", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-adaptation", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-inheritance", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-102-natural-selection-adaptation.yaml"}}$J$::jsonb, 'draft'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', v_project_id, 'substrand', $J$The Four-Component Natural Selection Mechanism$J$, $J$Key concepts: Natural Selection, Fitness, Selection Pressure, Drift, Gene, Allele, Mutation$J$, $J$6-8$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-natural-selection-adaptation-68", "performanceIndicators": ["Articulates all four components of natural selection (variation, heritability, differential reproduction, population-level frequency change) for a given example.", "Defines fitness as relative reproductive success, not individual strength or health.", "Distinguishes change in trait frequency caused by selection pressure from change caused by random drift.", "Applies the four-component model to at least two structurally different examples (trait gain and trait loss)."], "concepts": [{"id": "OE-CONCEPT-bio-core-natural-selection", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-fitness", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-selection-pressure", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-drift", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-gene", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-allele", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-mutation", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-102-natural-selection-adaptation.yaml"}}$J$::jsonb, 'draft'),
  ('b8bf5ec4-fe31-593a-8177-15b8109517b4', v_project_id, 'substrand', $J$Evaluating Adaptationist Claims$J$, $J$Key concepts: Adaptation, Fitness, Drift, Selection Pressure, Mutation, Population$J$, $J$9-12$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-natural-selection-adaptation-912", "performanceIndicators": ["Evaluates a proposed adaptationist explanation for a trait against alternative hypotheses (drift, developmental constraint, correlated trait).", "Applies the natural selection framework to unfamiliar organisms and trait types without being misled by surface features of the case.", "Explains why not every trait present in a population needs to be an adaptation."], "concepts": [{"id": "OE-CONCEPT-bio-core-adaptation", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-fitness", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-drift", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-selection-pressure", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-mutation", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-population", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-102-natural-selection-adaptation.yaml"}, "relations": {"prerequisiteOf": ["OE-STRAND-bio-core-k12-speciation-diversity-912"]}}$J$::jsonb, 'draft'),
  ('d561e9fc-f767-5d25-94dc-6a4715f8ecd4', v_project_id, 'strand', $J$Speciation and Diversity of Life$J$, $J$Macroevolutionary strand. Depends heavily on Strand 1 (population, allele) and Strand 2 (natural selection, selection pressure, drift) as the mechanisms that drive divergence -- this strand is where horizontal coherence is most heavily exercised, since almost every performance indicator here reinforces a concept introduced in one of the other two strands rather than introducing self-contained new mechanisms.$J$, $J$K-12$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-speciation-diversity", "description": "Macroevolutionary strand. Depends heavily on Strand 1 (population, allele) and Strand 2 (natural selection, selection pressure, drift) as the mechanisms that drive divergence -- this strand is where horizontal coherence is most heavily exercised, since almost every performance indicator here reinforces a concept introduced in one of the other two strands rather than introducing self-contained new mechanisms.", "associatedDomains": ["Biology"], "relations": {"prerequisiteOf": []}, "epistemicStatus": "designed-thought-experiment", "_source": {"repo": "bio-core-k12", "path": "strands/strand-103-speciation-diversity.yaml"}}$J$::jsonb, 'draft'),
  ('76c205d2-33d4-5532-ba5a-cab715380b5e', v_project_id, 'substrand', $J$Many Different Kinds of Living Things$J$, $J$Key concepts: Species, Extinction$J$, $J$K-2$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-speciation-diversity-k2", "performanceIndicators": ["Sorts organisms into groups based on shared observable features.", "Recognizes that some kinds of living things existed long ago and no longer exist today (e.g., dinosaurs)."], "concepts": [{"id": "OE-CONCEPT-bio-core-species", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-extinction", "emphasis": "primary"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-103-speciation-diversity.yaml"}}$J$::jsonb, 'draft'),
  ('a4cd9b9e-d3a1-52bd-b76f-eb6173ab7259', v_project_id, 'substrand', $J$Species, Relatedness, and Extinction$J$, $J$Key concepts: Species, Common Ancestor, Extinction$J$, $J$3-5$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-speciation-diversity-35", "performanceIndicators": ["Describes a species as a group of organisms that can reproduce with one another.", "Uses a simple diagram to show that two different species can share an ancestor further back in time.", "Explains that extinction means a species is permanently gone, not temporarily hidden."], "concepts": [{"id": "OE-CONCEPT-bio-core-species", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-common-ancestor", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-extinction", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-103-speciation-diversity.yaml"}}$J$::jsonb, 'draft'),
  ('ca152c60-d9a5-509f-afdb-e2e7bdf983b4', v_project_id, 'substrand', $J$How Populations Become New Species$J$, $J$Key concepts: Speciation, Phylogeny, Species, Population, Natural Selection, Selection Pressure$J$, $J$6-8$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-speciation-diversity-68", "performanceIndicators": ["Explains speciation as the process by which populations diverge until they can no longer interbreed.", "Explains that different selection pressures acting on separated populations can drive this divergence.", "Reads and constructs a simple phylogenetic tree to represent relatedness among species."], "concepts": [{"id": "OE-CONCEPT-bio-core-speciation", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-phylogeny", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-species", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-population", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-natural-selection", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-selection-pressure", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-103-speciation-diversity.yaml"}}$J$::jsonb, 'draft'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', v_project_id, 'substrand', $J$Evidence, Deep Time, and Patterns of Extinction$J$, $J$Key concepts: Phylogeny, Common Ancestor, Extinction, Allele, Mutation, Drift$J$, $J$9-12$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-bio-core-k12-speciation-diversity-912", "performanceIndicators": ["Constructs a phylogeny from morphological and molecular evidence and justifies the placement of a common ancestor node.", "Distinguishes background extinction rate from mass extinction events using fossil record evidence.", "Evaluates a claim of common ancestry using multiple independent lines of evidence (genetic, morphological, biogeographic)."], "concepts": [{"id": "OE-CONCEPT-bio-core-phylogeny", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-common-ancestor", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-extinction", "emphasis": "primary"}, {"id": "OE-CONCEPT-bio-core-allele", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-mutation", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-bio-core-drift", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "bio-core-k12", "path": "strands/strand-103-speciation-diversity.yaml"}}$J$::jsonb, 'draft')
