  INSERT INTO lpm_schema_elements (id, project_id, element_type, label, parent_id, metadata, status)
  VALUES
  ('993c989a-79d2-5262-b20f-9636504623cd', v_project_id, 'concept', $J$Agency$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-agency", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "The capacity of an individual or system to act intentionally and make choices that influence outcomes, rather than responding passively to external forces."}$J$::jsonb, 'accepted'),
  ('4e4ec762-ee46-53d3-afe3-da41c3d3f6af', v_project_id, 'concept', $J$Collective Intelligence$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-collective-intelligence", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Problem-solving or knowledge-generating capability that emerges from the coordinated activity of many individuals or agents, exceeding what any one could achieve alone."}$J$::jsonb, 'accepted'),
  ('301b8eed-edd6-5c71-91df-5219467c24fb', v_project_id, 'concept', $J$Communication$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-communication", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "The exchange of information between agents via signals, language, or other shared codes."}$J$::jsonb, 'accepted'),
  ('bd8381b9-7a20-5940-b9ec-5b053c75ea8e', v_project_id, 'concept', $J$Conflict$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-conflict", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Competing interests, goals, or behaviors among individuals or groups within a shared system or environment."}$J$::jsonb, 'accepted'),
  ('c13c4fe4-a865-52b5-9203-154e5934dd92', v_project_id, 'concept', $J$Cooperation$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-cooperation", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Coordinated behavior among individuals or groups that produces a mutual benefit not achievable, or less efficiently achieved, alone."}$J$::jsonb, 'accepted'),
  ('8c0525a4-0873-52c6-a097-8915714a33ae', v_project_id, 'concept', $J$Culture$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-culture", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Socially transmitted knowledge, beliefs, practices, and artifacts shared within a group, persisting beyond any single individual."}$J$::jsonb, 'accepted'),
  ('0254d031-dbdf-5a23-ab7b-c5046e0ac80f', v_project_id, 'concept', $J$Development$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-development", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "The process by which an organism grows and matures from an initial state toward greater complexity or capability; in education, the progressive growth of a learner's knowledge, skills, or competencies over time, often scaffolded by instruction."}$J$::jsonb, 'accepted'),
  ('b889941f-8b31-56a6-aef3-e3e9f26f79ca', v_project_id, 'concept', $J$Distributed Cognition$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-distributed-cognition", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Cognitive processing that is spread across individuals, artifacts, and environment, rather than occurring solely within a single mind."}$J$::jsonb, 'accepted'),
  ('212e3ab0-5575-572b-89fe-cff0ab90594d', v_project_id, 'concept', $J$Evolutionary Process$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-evolutionary-process", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Any process by which variants are generated, selected, and transmitted across iterations within a system -- applicable to genetic, cultural, technological, or cognitive systems alike."}$J$::jsonb, 'accepted'),
  ('6c5398e6-801c-55f9-9732-a018ba999e6b', v_project_id, 'concept', $J$Information$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-information", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "A pattern or signal that reduces uncertainty for a receiver, whether encoded genetically, linguistically, symbolically, or computationally."}$J$::jsonb, 'accepted'),
  ('71010850-ffce-5968-b6a5-38c0b8599620', v_project_id, 'concept', $J$Inheritance$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-inheritance", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Transmission of genetic information from parent to offspring (biology); of beliefs, practices, or knowledge from one generation or individual to another via social learning (culture); or persistence of design features or code structure across successive versions of an artifact or system (technology)."}$J$::jsonb, 'accepted'),
  ('183d2755-1489-554c-9b9e-e2cc8792592e', v_project_id, 'concept', $J$Innovation$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-innovation", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "The generation of a novel variant -- an idea, practice, technology, or trait -- that did not previously exist within a system."}$J$::jsonb, 'accepted'),
  ('4ebf512e-ba71-59c4-8e93-e03007a9d829', v_project_id, 'concept', $J$Institutions$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-institutions", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Stable, socially recognized structures or rules that organize and constrain collective behavior over time."}$J$::jsonb, 'accepted'),
  ('b9faf219-7d7f-5791-abca-c738d6130497', v_project_id, 'concept', $J$Knowledge$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-knowledge", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Justified, retained information that an individual, group, or system can draw upon to act or reason."}$J$::jsonb, 'accepted'),
  ('241ac4b1-00b3-517c-b3b5-10029f1efdc6', v_project_id, 'concept', $J$Learning$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-learning", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "A relatively durable change in knowledge, behavior, or capability resulting from experience, instruction, or practice."}$J$::jsonb, 'accepted'),
  ('3756d347-25a4-5484-bac4-2a3a061f6def', v_project_id, 'concept', $J$Niche Construction$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-niche-construction", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "The process by which organisms or groups modify their environment in ways that alter the selective pressures acting on themselves or others."}$J$::jsonb, 'accepted'),
  ('c529c772-66e2-5915-93f8-adedafc7732d', v_project_id, 'concept', $J$Norms$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-norms", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Shared expectations or rules of behavior within a group, enforced through social sanction rather than formal law."}$J$::jsonb, 'accepted'),
  ('fe387dcf-751c-59e6-9fa2-8fcc6abecea3', v_project_id, 'concept', $J$Representation$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-representation", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "A structure -- mental, symbolic, or computational -- that stands for and conveys meaning about something else."}$J$::jsonb, 'accepted'),
  ('e09d4837-14bf-5d3f-839f-f708e982b216', v_project_id, 'concept', $J$Scaffolding$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-scaffolding", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Temporary structured support provided to a learner, gradually withdrawn as competence increases."}$J$::jsonb, 'accepted'),
  ('0573db35-8451-5189-998c-8619ea1d26ec', v_project_id, 'concept', $J$Selection$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-selection", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Differential reproductive success among heritable variants (biology); differential persistence or spread of cultural variants based on their fit to a social or environmental context (culture); choosing among available instructional pathways or resources (education); a search or optimization process that favors candidates scoring higher against an objective function (AI)."}$J$::jsonb, 'accepted'),
  ('b0040254-6692-5ff3-8c4a-41b7a0bd1e51', v_project_id, 'concept', $J$Teaching$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-teaching", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Intentional action by one individual or system to facilitate another's learning or transmission of a skill, practice, or piece of knowledge."}$J$::jsonb, 'accepted'),
  ('1d89ba05-d574-53ea-aaa9-c513d9125e96', v_project_id, 'concept', $J$Technology$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-technology", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Tools, techniques, or systems created to extend or augment biological or cognitive capability."}$J$::jsonb, 'accepted'),
  ('0a1dc107-eeca-53a2-8a29-056c0f7b70df', v_project_id, 'concept', $J$Transmission$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-transmission", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "The process by which information, traits, or practices move from one holder (organism, person, group, or system) to another."}$J$::jsonb, 'accepted'),
  ('877daea8-799c-5c43-920a-b7d3fc131c80', v_project_id, 'concept', $J$Variation$J$, NULL, $J${"conceptbase_id": "OE-CONCEPT-oe-interdisciplinary-variation", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "The existence of differences among individuals, variants, or instances within a population or system, providing the raw material on which selection can act."}$J$::jsonb, 'accepted'),
  ('e6f78871-2017-55c6-8739-9a9c3a249315', v_project_id, 'concept', $J$Theory of Mind$J$, NULL, $J${"conceptbase_id": "OE-SANDBOX-CONCEPT-000010", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "The capacity to attribute mental states -- beliefs, desires, intentions, knowledge -- to oneself and others, and to use those attributions to interpret and predict behavior."}$J$::jsonb, 'proposed'),
  ('575e2873-964e-56c1-88ef-8908791c8f92', v_project_id, 'concept', $J$Metacognition$J$, NULL, $J${"conceptbase_id": "OE-SANDBOX-CONCEPT-000011", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "The capacity to monitor, evaluate, and regulate one's own cognitive processes -- knowing what one knows, tracking how one is thinking, and adjusting strategies accordingly."}$J$::jsonb, 'proposed'),
  ('ce917c30-aaf6-59a9-b20a-36ecebf5b68f', v_project_id, 'concept', $J$Intuitive Theories$J$, NULL, $J${"conceptbase_id": "OE-SANDBOX-CONCEPT-000012", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Informal, domain-specific causal frameworks -- folk physics, folk biology, folk psychology -- that people spontaneously construct to explain and predict how the world works, typically without formal instruction."}$J$::jsonb, 'proposed'),
  ('7c75aef6-b615-572a-aa01-b2c82591cd2f', v_project_id, 'concept', $J$Analogical Reasoning$J$, NULL, $J${"conceptbase_id": "OE-SANDBOX-CONCEPT-000013", "vocabulary": "OE-INTERDISCIPLINARY-v1.0.0", "definition": "Generating or evaluating a new idea by mapping the structure of an already-familiar case onto an unfamiliar one -- starting a search for a solution from whichever known example is most similar to the target, rather than starting from nothing, and checking which parts of the familiar case do and do not carry over."}$J$::jsonb, 'proposed')
  INSERT INTO lpm_data_objects (id, project_id, object_type, title, description, grade_band, subject_area, content, status)
  VALUES
  ('5e4cdc6e-5c25-5f21-a833-4c0859a609da', v_project_id, 'strand', $J$Inheritance, Variation, and Selection Across Systems$J$, $J$Foundational cross-domain strand. Uses the OE-INTERDISCIPLINARY Selection concept's four discipline-specific definitions (biology, culture, education, AI) as the strand's organizing device: rather than teaching biological selection first and analogizing outward, students encounter biological and cultural cases side by side from an early grade band, with full multi-disciplinary comparison reserved for 9-12.$J$, $J$K-12$J$, $J$Biology, Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-inheritance-variation-selection", "description": "Foundational cross-domain strand. Uses the OE-INTERDISCIPLINARY Selection concept's four discipline-specific definitions (biology, culture, education, AI) as the strand's organizing device: rather than teaching biological selection first and analogizing outward, students encounter biological and cultural cases side by side from an early grade band, with full multi-disciplinary comparison reserved for 9-12.", "associatedDomains": ["Biology", "Social Studies"], "relations": {"prerequisiteOf": ["OE-STRAND-oe-interdisciplinary-k12-culture-technology-collective"], "foundationalTo": ["OE-STRAND-oe-interdisciplinary-k12-agency-development-niche", "OE-STRAND-oe-interdisciplinary-k12-analogy-search-metacognition"]}, "epistemicStatus": "designed-thought-experiment", "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-201-inheritance-variation-selection.yaml"}}$J$::jsonb, 'draft'),
  ('04d57493-ac2f-5ec6-a1ba-0596eae3158a', v_project_id, 'substrand', $J$Things That Get Passed On$J$, $J$Key concepts: Inheritance, Variation$J$, $J$K-2$J$, $J$Biology, Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-inheritance-variation-selection-k2", "performanceIndicators": ["Describes a trait passed from parent to child (eye color) and a story or recipe passed from grandparent to grandchild, side by side.", "Notices that individuals within a family, and versions of a story told by different people, both show variation."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-inheritance", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-variation", "emphasis": "primary"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-201-inheritance-variation-selection.yaml"}}$J$::jsonb, 'draft'),
  ('db1fca08-0dcf-5910-a3df-2de902e8630a', v_project_id, 'substrand', $J$Comparing Biological and Cultural Transmission$J$, $J$Key concepts: Inheritance, Transmission, Variation$J$, $J$3-5$J$, $J$Biology, Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-inheritance-variation-selection-35", "performanceIndicators": ["Compares how a genetic trait moves from parent to offspring with how a game's rules move from one group of kids to another.", "Identifies that both processes involve a 'holder' passing something to a new 'holder,' with some change possible along the way."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-inheritance", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-transmission", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-variation", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-201-inheritance-variation-selection.yaml"}}$J$::jsonb, 'draft'),
  ('6315aad7-35b7-52dc-9dd2-1b82d707a768', v_project_id, 'substrand', $J$The General Pattern: Variation, Selection, Transmission$J$, $J$Key concepts: Evolutionary Process, Selection, Variation, Transmission, Information$J$, $J$6-8$J$, $J$Biology, Social Studies, Computer Science$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-inheritance-variation-selection-68", "performanceIndicators": ["Describes the general pattern (variation -> selection -> transmission) using the Evolutionary Process concept.", "Applies this general pattern in parallel to one biological case (e.g., beak shape in a bird population) and one cultural case (e.g., which version of a phone app feature gets kept).", "Uses the Selection concept's biology and culture definitions side by side and identifies what is similar and different between them.", "Explains that what actually gets transmitted in both the biological case (a gene) and the cultural case (an app feature's design) is information -- a pattern that reduces uncertainty for the receiver about which trait or version to expect -- not the physical material itself, using the Information concept explicitly rather than leaving 'passing something on' unanalyzed."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-evolutionary-process", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-selection", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-variation", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-transmission", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-information", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-201-inheritance-variation-selection.yaml"}}$J$::jsonb, 'draft'),
  ('396e3dd9-4f22-5160-b6c7-3752caefa1b8', v_project_id, 'substrand', $J$Selection Across Biology, Culture, Education, and AI$J$, $J$Key concepts: Selection, Evolutionary Process, Inheritance, Variation, Transmission$J$, $J$9-12$J$, $J$Biology, Social Studies, Computer Science$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-inheritance-variation-selection-912", "performanceIndicators": ["Compares all four disciplinary definitions of Selection (biology, culture, education, AI) for a single unifying feature: differential persistence of variants.", "Explains what is genuinely analogous and what is genuinely different between biological selection and algorithmic selection (e.g., a genetic algorithm's fitness function).", "Constructs an original example of Selection in a domain not covered by the vocabulary's existing examples and justifies its classification."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-selection", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-evolutionary-process", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-inheritance", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-variation", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-transmission", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-201-inheritance-variation-selection.yaml"}}$J$::jsonb, 'draft'),
  ('408a667a-93d5-58a1-bb50-f8e6606b9745', v_project_id, 'strand', $J$Agency, Development, and Niche Construction$J$, $J$This strand exists only because OE-INTERDISCIPLINARY defines Agency and Niche Construction as first-class concepts -- BIO-CORE has no equivalent, so LPM A has no counterpart strand. Deliberately reinforces Strand 1's Selection concept throughout (behavior as a factor shaping what gets selected) rather than treating agency as a separate, unrelated topic.$J$, $J$K-12$J$, $J$Biology, Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-agency-development-niche", "description": "This strand exists only because OE-INTERDISCIPLINARY defines Agency and Niche Construction as first-class concepts -- BIO-CORE has no equivalent, so LPM A has no counterpart strand. Deliberately reinforces Strand 1's Selection concept throughout (behavior as a factor shaping what gets selected) rather than treating agency as a separate, unrelated topic.", "associatedDomains": ["Biology", "Social Studies"], "relations": {"prerequisiteOf": ["OE-STRAND-oe-interdisciplinary-k12-culture-technology-collective"]}, "epistemicStatus": "designed-thought-experiment", "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-202-agency-development-niche.yaml"}, "disputeInstantiation": "This strand instantiates the integrated-causal-reasoning (ICR) position (TheoryBase OE-THEORY-integrated-causal-reasoning) in the real, published dispute with Kampourakis (2020) / Nehm & Kampourakis (2022) -- see openevo-graph's nodes/disputes/dispute-openevo-vs-kampourakis.yaml, whose instantiatesIn edge already points at this strand's id."}$J$::jsonb, 'draft'),
  ('6f04ee30-2be3-537b-9d0e-b339d9fed79c', v_project_id, 'substrand', $J$Living Things Act to Meet Their Needs$J$, $J$Key concepts: Agency, Development$J$, $J$K-2$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-agency-development-niche-k2", "performanceIndicators": ["Describes what an animal does to find food, stay safe, or care for its young.", "Describes ways a person or animal grows and changes as it gets older.", "Recognizes that acting to meet a need does not require the same kind of thinking a person does."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-agency", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-development", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-202-agency-development-niche.yaml"}}$J$::jsonb, 'draft'),
  ('31b2be29-7a8c-5f98-a447-55ecf57f1ff9', v_project_id, 'substrand', $J$Comparing How Different Living Things Act, Learn, and Teach$J$, $J$Key concepts: Agency, Learning, Teaching, Scaffolding$J$, $J$3-5$J$, $J$Biology, Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-agency-development-niche-35", "performanceIndicators": ["Compares goal-directed behavior across two different species and describes how their capacities differ.", "Describes an example of an animal or person learning a behavior by watching another individual.", "Describes a simple example of scaffolding (a helper providing support that is gradually reduced as skill grows)."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-agency", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-learning", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-teaching", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-scaffolding", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-202-agency-development-niche.yaml"}}$J$::jsonb, 'draft'),
  ('3a112595-4435-5db0-950d-ca7c6da5160d', v_project_id, 'substrand', $J$Agency, Niche Construction, and Selection$J$, $J$Key concepts: Agency, Niche Construction, Development, Selection$J$, $J$6-8$J$, $J$Biology$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-agency-development-niche-68", "performanceIndicators": ["Defines agency as a capacity to regulate behavior toward a goal-state, without requiring conscious intention.", "Explains niche construction using an example of an organism modifying its own environment (e.g., an earthworm improving soil) in a way that changes what gets selected in later generations.", "Explains how a behavior (agency) and a selection process (Strand 1) can be connected without invoking evolutionary foresight."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-agency", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-niche-construction", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-development", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-selection", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-202-agency-development-niche.yaml"}}$J$::jsonb, 'draft'),
  ('5d938d91-e81b-516c-ba58-a234b6d5559f', v_project_id, 'substrand', $J$Agency and Niche Construction Across Biological and Technological Systems$J$, $J$Key concepts: Agency, Niche Construction, Learning, Teaching, Selection, Information, Communication$J$, $J$9-12$J$, $J$Biology, Computer Science, Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-agency-development-niche-912", "performanceIndicators": ["Places several organisms (bacterium, bird, chimpanzee, human) along an agency spectrum and justifies each placement.", "Compares biological niche construction (earthworms, beavers) with human-technological niche construction (cities, digital information environments).", "Analyzes a case where a designed system (e.g., a recommendation algorithm) exhibits both intentional design (agency) and emergent, non-designed behavior.", "Names information processing as the shared substrate across all three cases in this sub-strand -- a nervous system converting stimuli into signals, a recommendation algorithm converting user data into output, and teaching/learning (Strand 2's own Learning/Teaching concepts) as the deliberate Communication of information between individuals -- and explains what stays the same and what genuinely differs about how each system encodes, transmits, and acts on it."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-agency", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-niche-construction", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-learning", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-teaching", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-selection", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-information", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-communication", "emphasis": "reinforcing"}], "required": false, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-202-agency-development-niche.yaml"}, "note": "Marked optional (elective/regional extension) at this specific sub-strand only -- the AI-system application is treated as an advanced extension, not core content, consistent with the phased, cautious approach to frontier interdisciplinary territory."}$J$::jsonb, 'draft'),
  ('9d59fa89-cdc8-5147-a71e-95175b25fcee', v_project_id, 'strand', $J$Culture, Technology, and Collective Systems$J$, $J$The broadest strand, drawing on OE-INTERDISCIPLINARY's social/cultural concepts. Deliberately reinforces Strand 1 (Transmission, Selection, Innovation-as-variation-generator) and Strand 2 (Agency, Niche Construction) throughout, so that by 9-12 all three strands converge on a shared explanatory vocabulary rather than remaining parallel tracks.$J$, $J$K-12$J$, $J$Social Studies, Computer Science$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-culture-technology-collective", "description": "The broadest strand, drawing on OE-INTERDISCIPLINARY's social/cultural concepts. Deliberately reinforces Strand 1 (Transmission, Selection, Innovation-as-variation-generator) and Strand 2 (Agency, Niche Construction) throughout, so that by 9-12 all three strands converge on a shared explanatory vocabulary rather than remaining parallel tracks.", "associatedDomains": ["Social Studies", "Computer Science"], "relations": {"prerequisiteOf": []}, "epistemicStatus": "designed-thought-experiment", "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-203-culture-technology-collective.yaml"}}$J$::jsonb, 'draft'),
  ('9fc65a59-5de1-51ad-ad30-a9c0faca177a', v_project_id, 'substrand', $J$Groups, Rules, and Tools$J$, $J$Key concepts: Culture, Technology, Communication$J$, $J$K-2$J$, $J$Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-culture-technology-collective-k2", "performanceIndicators": ["Describes a shared rule or custom that a family or classroom group follows.", "Identifies a tool that people use and describes what it helps them do.", "Describes a way people share ideas with each other (talking, drawing, signs)."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-culture", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-technology", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-communication", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-203-culture-technology-collective.yaml"}}$J$::jsonb, 'draft'),
  ('a1bc92d8-3730-53b8-a059-f3999e4387cf', v_project_id, 'substrand', $J$Comparing Communities and Changing Tools Over Time$J$, $J$Key concepts: Culture, Cooperation, Conflict, Innovation$J$, $J$3-5$J$, $J$Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-culture-technology-collective-35", "performanceIndicators": ["Compares practices of two different communities and identifies at least one similarity and one difference.", "Describes an example of cooperation and an example of conflict within a group working toward a goal.", "Traces a simple history of a tool (e.g., writing instruments) showing how new versions built on older ones."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-culture", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-cooperation", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-conflict", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-innovation", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-203-culture-technology-collective.yaml"}}$J$::jsonb, 'draft'),
  ('ad0173a4-5c64-5d05-96ac-2b61810c4153', v_project_id, 'substrand', $J$Culture as Transmitted, Institutions as Stabilizing Structures$J$, $J$Key concepts: Culture, Institutions, Norms, Information, Representation, Transmission, Innovation$J$, $J$6-8$J$, $J$Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-culture-technology-collective-68", "performanceIndicators": ["Explains culture as socially transmitted knowledge and practice that persists beyond any one individual, using the Transmission concept from Strand 1.", "Distinguishes an institution (a stable, rule-based structure) from a norm (an informal shared expectation).", "Identifies an innovation (a novel cultural variant) and traces how it did or did not spread through a community."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-culture", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-institutions", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-norms", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-information", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-representation", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-transmission", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-innovation", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-203-culture-technology-collective.yaml"}}$J$::jsonb, 'draft'),
  ('e820dc2d-9317-57d1-8475-22a701fc486a', v_project_id, 'substrand', $J$Collective Intelligence, Distributed Cognition, and Coevolving Technology$J$, $J$Key concepts: Collective Intelligence, Distributed Cognition, Technology, Knowledge, Agency, Niche Construction, Selection$J$, $J$9-12$J$, $J$Social Studies, Computer Science, Biology$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-culture-technology-collective-912", "performanceIndicators": ["Explains how a group-level outcome (collective intelligence) can emerge from many individual agents without any one agent designing the outcome, connecting to Strand 2's Agency concept.", "Analyzes an example of distributed cognition (knowledge or processing spread across people and tools/artifacts, not held by one mind).", "Explains how human technological niche construction (Strand 2) and cultural selection (Strand 1) jointly shape a contemporary information environment (e.g., a social media platform)."], "concepts": [{"id": "OE-CONCEPT-oe-interdisciplinary-collective-intelligence", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-distributed-cognition", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-technology", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-knowledge", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-agency", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-niche-construction", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-selection", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-203-culture-technology-collective.yaml"}}$J$::jsonb, 'draft'),
  ('06af1b7b-19bb-5d77-87ac-52f34650f556', v_project_id, 'strand', $J$Discovering and Testing Ideas: Analogy, Search, and the Growth of Understanding$J$, $J$This strand exists only because OE-INTERDISCIPLINARY defines Analogical Reasoning and Metacognition as first-class concepts -- BIO-CORE has no equivalent, so LPM A (bio-core-k12) has no counterpart strand, the same reason Strand 2 (Agency/Niche Construction) has none either. A strand about how minds, cultures, and science itself come up with better ideas -- not by searching everything at once, but by starting from whatever known case is most similar to the new problem, trying a small change, and$J$, $J$K-12$J$, $J$Science, Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-analogy-search-metacognition", "description": "This strand exists only because OE-INTERDISCIPLINARY defines Analogical Reasoning and Metacognition as first-class concepts -- BIO-CORE has no equivalent, so LPM A (bio-core-k12) has no counterpart strand, the same reason Strand 2 (Agency/Niche Construction) has none either. A strand about how minds, cultures, and science itself come up with better ideas -- not by searching everything at once, but by starting from whatever known case is most similar to the new problem, trying a small change, and keeping what works. Reinforces Strand 1's Selection/Variation/Evolutionary Process vocabulary and Strand 3's Innovation/Culture vocabulary throughout. Unlike Strands 1-3, this strand's youngest bands are grounded directly in validated developmental-psychology task batteries (Pillow & Pearson's controllability studies), not just age-plausible design judgment.", "associatedDomains": ["Science", "Social Studies"], "relations": {"prerequisiteOf": [], "foundationalTo": []}, "epistemicStatus": "designed-thought-experiment", "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-204-analogy-search-metacognition.yaml"}}$J$::jsonb, 'draft'),
  ('8363df74-ecd8-54e9-82f1-e93623f9995c', v_project_id, 'substrand', $J$Ideas That Are Like Other Ideas$J$, $J$Key concepts: Analogical Reasoning, Variation, Theory of Mind$J$, $J$K-2$J$, $J$Science, Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-analogy-search-metacognition-k2", "performanceIndicators": ["Uses something already known (a favorite story, a familiar game, a tool used before) to help figure out something new, and can say what about the new thing reminds them of the old one -- an early, informal version of the Variation concept from Strand 1 (noticing that things can be similar in some ways and different in others).", "With a partner, tries a new solution to a simple problem (building blocks, a puzzle) by first asking 'what does this remind me of that I've solved before?', and describes whether it helped.", "Explains a simple action in terms of what the person wanted -- 'she reached for the cup because she wanted a drink' -- as an early, natural way of noticing that people's actions make sense in light of their goals.", "With adult guidance, sorts two activities into 'takes work to do' and 'just happens without trying' -- without this sorting needing to be fully consistent yet."], "concepts": [{"id": "OE-SANDBOX-CONCEPT-000013", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-variation", "emphasis": "reinforcing"}, {"id": "OE-SANDBOX-CONCEPT-000010", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-204-analogy-search-metacognition.yaml"}}$J$::jsonb, 'draft'),
  ('a64224d1-ac36-5b1c-b475-3c5af3aa4656', v_project_id, 'substrand', $J$Good Guesses, Better Guesses: Testing Ideas$J$, $J$Key concepts: Analogical Reasoning, Selection, Metacognition$J$, $J$3-5$J$, $J$Science, Social Studies$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-analogy-search-metacognition-35", "performanceIndicators": ["Explains, using a familiar example (e.g. a breeder choosing which animals or plants to raise the next generation from because of a trait they want), how deliberately keeping 'the best version so far' over many rounds can add up to a big change, even though each single round's change is small -- the same Selection concept from Strand 1, applied here to how ideas themselves get kept or dropped, not just to living things.", "Tries a short set of real, research-based 'does this take effort?' tasks and rates how much effort and how much choice each one involved, comparing ratings with a partner (adapted directly from Pillow & Pearson's own task battery).", "Plays a simple 'guess my rule' game (proposes new examples to test a hidden pattern, gets told yes or no) and afterward reflects on whether their guesses mostly tried to confirm their first idea or tried to test it in a way that could prove it wrong.", "Describes a specific time their own first guess about how something worked turned out to be wrong, and what changed their mind."], "concepts": [{"id": "OE-SANDBOX-CONCEPT-000013", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-selection", "emphasis": "primary"}, {"id": "OE-SANDBOX-CONCEPT-000011", "emphasis": "primary"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-204-analogy-search-metacognition.yaml"}}$J$::jsonb, 'draft'),
  ('d2dc3119-7af8-55d8-8bfe-b63a4ec56acb', v_project_id, 'substrand', $J$How Minds and Cultures Search for Better Ideas$J$, $J$Key concepts: Analogical Reasoning, Metacognition, Innovation, Evolutionary Process$J$, $J$6-8$J$, $J$Science, Social Studies, Computer Science$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-analogy-search-metacognition-68", "performanceIndicators": ["Compares two ways of tackling an unfamiliar problem -- starting from a random guess versus starting from the closest already-known example -- and explains why starting from a good example is usually faster, even though it isn't guaranteed to work.", "Explains why a person's next new idea is almost always a small change to their current idea rather than something completely different, using their own experience revising an essay, a design, or a model as the example -- connecting explicitly to the Evolutionary Process concept's variation-selection-transmission pattern from Strand 1.", "Identifies a case where only looking for evidence that confirms a first guess (rather than evidence that could disprove it) led to a wrong conclusion, and explains why this can happen to careful thinkers, not only careless ones.", "Explains how a shared, remembered pool of solved examples -- a class's worked-example library, a culture's stock of stories or tools -- makes each new problem faster to solve for everyone who can draw on it, using the Innovation and Culture concepts from Strand 3.", "Locates their own current understanding of one specific cognitive activity on a rough progression from 'it's just a thing my brain does' toward 'a process with its own reliability that I can evaluate and sometimes deliberately control' (adapted from Zdybel's 2021 phenomenographical categories)."], "concepts": [{"id": "OE-SANDBOX-CONCEPT-000013", "emphasis": "primary"}, {"id": "OE-SANDBOX-CONCEPT-000011", "emphasis": "primary"}, {"id": "OE-CONCEPT-oe-interdisciplinary-innovation", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-evolutionary-process", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-204-analogy-search-metacognition.yaml"}}$J$::jsonb, 'draft'),
  ('ba60a3be-0135-5b53-b88f-a7aecfe0ed96', v_project_id, 'substrand', $J$The Shared Structure of Discovery: Darwin's Notebooks and the History of Science$J$, $J$Key concepts: Analogical Reasoning, Metacognition, Intuitive Theories, Selection$J$, $J$9-12$J$, $J$Science, Social Studies, Computer Science$J$, $J${"source_id": "OE-STRAND-oe-interdisciplinary-k12-analogy-search-metacognition-912", "performanceIndicators": ["Traces Charles Darwin's use of the artificial-selection/natural-selection analogy across his own notebooks as a documented, historical case of analogy-driven scientific discovery, distinguishing it from Darwin's own later retrospective claim to have proceeded without any prior theory.", "Takes and defends a position on the 'child-as-scientist' debate: is a young child's everyday theory-revision the same kind of process as a scientist's theory change, or is deliberate, explicit coordination of theory and evidence a categorically different, later-developing capacity?", "Explains why confirmation bias is difficult to fully eliminate even for trained scientists, using the idea that any search for a solution can only test ideas that have actually been generated, not the full space of every possible idea.", "Describes organized science as a cultural system that changes over historical time through the same general pattern -- new ideas proposed, then kept or dropped based on how well they work -- that shapes a language, a set of tools, or a curriculum.", "Runs or interprets a simple computational demonstration (an NK-landscape hill-climbing model) comparing how starting a search from a well-matched known example versus a random starting point changes how quickly and reliably a good solution is found, and connects the quantitative result back to their own experience revising a project, essay, or design."], "concepts": [{"id": "OE-SANDBOX-CONCEPT-000013", "emphasis": "primary"}, {"id": "OE-SANDBOX-CONCEPT-000011", "emphasis": "primary"}, {"id": "OE-SANDBOX-CONCEPT-000012", "emphasis": "reinforcing"}, {"id": "OE-CONCEPT-oe-interdisciplinary-selection", "emphasis": "reinforcing"}], "required": true, "_source": {"repo": "oe-interdisciplinary-k12", "path": "strands/strand-204-analogy-search-metacognition.yaml"}}$J$::jsonb, 'draft')
