-- bio-core-interdisciplinary-lpm-content-seed: populates the two existing, already-public
-- "Synthetic-Theoretical" Project Spaces (bio-core-lpm-synth / interdisciplinary-lpm-synth --
-- seeded empty by 005_seed_projects.sql, renamed by 074_rename_synthetic_pair_projects.sql,
-- still structurally empty as of this migration per 074's own comment) with the real
-- strand/substrand/concept content transcribed directly from the sibling bio-core-k12 and
-- oe-interdisciplinary-k12 GitHub repos (their current working-tree state, including an
-- already-decided identifier-scheme migration neither repo had committed yet). Generated by
-- scripts/generate_bio_core_interdisciplinary_lpm_seed.py, not hand-typed.
--
-- Purpose: this is the real content those two standalone repos exist to hold, moved into
-- OpenLPM so work can continue natively here and the standalone repos can be retired.
-- Concept labels/definitions are transcribed verbatim from conceptbase/registry/concept/*.json
-- (the real, already-published vocabulary records), not re-authored.
--
-- Scope: bio-core-k12's 3 strands (complete) and oe-interdisciplinary-k12's first 4 strands
-- (201-204, matching that repo's own lpm.yaml). Deliberately excludes a 5th strand
-- (rhetorical-tells-authenticity) that sits uncommitted in that repo's working tree, dated
-- 2026-10-03, not referenced by its own lpm.yaml, and self-flagged as proposing an
-- unregistered ConceptBase sandbox concept pending Dustin's review -- a follow-up once that
-- review happens, not folded in here by fiat.
--
-- Every epistemicStatus/epistemicStatusNote claim in the source repos (RFC-0019: these are
-- deliberately synthetic, designed-thought-experiment comparison objects, never field-tested
-- or recommended curriculum) is already carried by the existing projects.epistemic_status /
-- epistemic_status_note set in 005 -- unchanged by this migration, since it's still accurate.
--
-- Idempotency: all ids below are uuid5-derived (stable across re-runs); lpm_schema_elements
-- and lpm_data_objects inserts use ON CONFLICT (id) DO NOTHING, lpm_connections/
-- lpm_object_tags use their own real unique constraints -- safe to re-apply.

DO $MIGRATION$
DECLARE
  v_project_id UUID;
  v_user_id UUID;
BEGIN

  SELECT id INTO v_user_id FROM users WHERE email = 'dustin.eirdosh@eva.mpg.de';

  -- ==========================================================================
  -- Project: bio-core-lpm-synth
  -- ==========================================================================
  SELECT id INTO v_project_id FROM projects WHERE slug = $J$bio-core-lpm-synth$J$;
  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'Project slug bio-core-lpm-synth not found -- has it been renamed again since 074_rename_synthetic_pair_projects.sql? This migration needs re-pointing, not a silent skip.';
  END IF;

  VALUES (v_project_id, 'conceptbase', TRUE, FALSE)
  ON CONFLICT (project_id, base_repo) DO NOTHING;

  SELECT v_project_id, $J$bio-core-k12 (GitHub repo, retired after this migration)$J$, $J$YAML (ConceptBase oe:LPM / oe:Strand schema)$J$, $J$CC-BY-NC-SA-4.0 (OpenEvo Computational Curriculum Studies Working Group). Migrated from the standalone bio-core-k12 GitHub repo into this Project Space on 2026-10-03, preserving its content and provenance after the standalone repo was retired; structurally imported into lpm_data_objects/lpm_connections/lpm_object_tags by this migration, not merely declared.$J$, $J$https://github.com/openevo-ccs/bio-core-k12$J$
  WHERE NOT EXISTS (
    SELECT 1 FROM project_source_declarations
    WHERE project_id = v_project_id AND source_name = $J$bio-core-k12 (GitHub repo, retired after this migration)$J$
  );

  -- Concept vocabulary (15 elements, BIO-CORE-v1.0.0)
  ON CONFLICT (id) DO NOTHING;

  -- Strands and sub-strands
  ON CONFLICT (id) DO NOTHING;

  -- Connections: isChildOf (substrand -> strand) + the source's own declared
  -- strand/substrand relations (prerequisiteOf, foundationalTo), all 'asserted'/'accepted'
  -- since these are the source authors' own stated structure, not a new suggestion.
  ON CONFLICT (from_object_id, to_object_id, relation_type) DO NOTHING;

  -- Object tags: sub-strand -> concept, role = the source's own emphasis value
  -- ('primary' / 'reinforcing'), preserved verbatim rather than remapped.
  ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;

  IF v_user_id IS NULL THEN
    RAISE NOTICE 'No users row found for dustin.eirdosh@eva.mpg.de -- bio-core-lpm-synth seeded without checking/fixing ownership.';
  ELSE
    VALUES (v_project_id, v_user_id, 'owner')
    ON CONFLICT (project_id, user_id) DO UPDATE SET role = 'owner';

    UPDATE projects SET created_by = v_user_id
    WHERE id = v_project_id AND created_by IS NULL;
  END IF;

  -- ==========================================================================
  -- Project: interdisciplinary-lpm-synth
  -- ==========================================================================
  SELECT id INTO v_project_id FROM projects WHERE slug = $J$interdisciplinary-lpm-synth$J$;
  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'Project slug interdisciplinary-lpm-synth not found -- has it been renamed again since 074_rename_synthetic_pair_projects.sql? This migration needs re-pointing, not a silent skip.';
  END IF;

  VALUES (v_project_id, 'conceptbase', TRUE, FALSE)
  ON CONFLICT (project_id, base_repo) DO NOTHING;

  SELECT v_project_id, $J$oe-interdisciplinary-k12 (GitHub repo, retired after this migration)$J$, $J$YAML (ConceptBase oe:LPM / oe:Strand schema)$J$, $J$CC-BY-NC-SA-4.0 (OpenEvo Computational Curriculum Studies Working Group). Migrated from the standalone oe-interdisciplinary-k12 GitHub repo into this Project Space on 2026-10-03, preserving its content and provenance after the standalone repo was retired; structurally imported into lpm_data_objects/lpm_connections/lpm_object_tags by this migration, not merely declared. Scope note: that repo's working tree also contains a newer, uncommitted 5th strand (rhetorical-tells-authenticity) not yet referenced by its own lpm.yaml and explicitly flagged pending review -- deliberately not included here; a follow-up migration once reviewed.$J$, $J$https://github.com/openevo-ccs/interdisciplinary-k12$J$
  WHERE NOT EXISTS (
    SELECT 1 FROM project_source_declarations
    WHERE project_id = v_project_id AND source_name = $J$oe-interdisciplinary-k12 (GitHub repo, retired after this migration)$J$
  );

  -- Concept vocabulary (28 elements, OE-INTERDISCIPLINARY-v1.0.0)
  ON CONFLICT (id) DO NOTHING;

  -- Strands and sub-strands
  ON CONFLICT (id) DO NOTHING;

  -- Connections: isChildOf (substrand -> strand) + the source's own declared
  -- strand/substrand relations (prerequisiteOf, foundationalTo), all 'asserted'/'accepted'
  -- since these are the source authors' own stated structure, not a new suggestion.
  ON CONFLICT (from_object_id, to_object_id, relation_type) DO NOTHING;

  -- Object tags: sub-strand -> concept, role = the source's own emphasis value
  -- ('primary' / 'reinforcing'), preserved verbatim rather than remapped.
  ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;

  IF v_user_id IS NULL THEN
    RAISE NOTICE 'No users row found for dustin.eirdosh@eva.mpg.de -- interdisciplinary-lpm-synth seeded without checking/fixing ownership.';
  ELSE
    VALUES (v_project_id, v_user_id, 'owner')
    ON CONFLICT (project_id, user_id) DO UPDATE SET role = 'owner';

    UPDATE projects SET created_by = v_user_id
    WHERE id = v_project_id AND created_by IS NULL;
  END IF;

END $MIGRATION$;
